"""This file contains the Sim Dialogs Linac Page Object class for the SIM LINAC pane
in the Sim Dialogs XVI test tool"""

import logging
from . import SimDialogs
from .. interactions import SimDialogLinacFuncs


logger = logging.getLogger(__name__)

class SimDialogsLinac(SimDialogs):
    '''Page Object class for the SIM LINAC pane'''

    def __init__(self, host_address: str ="192.168.30.4") -> None:
        super().__init__(host_address)

    def toggle_sim_linac_node_online_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Node Online checkbox in the Sim Linac Pane to either checked
        or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            SimDialogLinacFuncs.check_sim_linac_node_online_checkbox()
        else:
            SimDialogLinacFuncs.uncheck_sim_linac_node_online_checkbox()

    def select_sim_linac_global_state_option(self, radio_btn_option: str) -> None:
        '''
        Select one of the radio button options for the Sim Collimator pane
        for the given radio button string

        Args:
            radio_btn_option (str): Name of radio button string to set

            radio_btn_option can be one of the following strings:
            "Reset", "Active", "Prepare", "Ready", or "Execute"
        '''
        if radio_btn_option.casefold() == "Reset".casefold():
            SimDialogLinacFuncs.click_sim_linac_global_state_reset_radio_button()
        elif radio_btn_option.casefold() == "Active".casefold():
            SimDialogLinacFuncs.click_sim_linac_global_state_active_radio_button()
        elif radio_btn_option.casefold() == "Prepare".casefold():
            SimDialogLinacFuncs.click_sim_linac_global_state_prepare_radio_button()
        elif radio_btn_option.casefold() == "Ready".casefold():
            SimDialogLinacFuncs.click_sim_linac_global_state_ready_radio_button()
        elif radio_btn_option.casefold() == "Execute".casefold():
            SimDialogLinacFuncs.click_sim_linac_global_state_execute_radio_button()
        else:
            logger.info(f"Invalid Sim Linac radio button option: {radio_btn_option}, unable to set")
